-- 7. ACTUALIZAR SECUENCIAS SERIALES
SELECT setval(pg_get_serial_sequence('roles', 'id'), COALESCE((SELECT MAX(id) FROM roles), 1));
SELECT setval(pg_get_serial_sequence('permissions', 'id'), COALESCE((SELECT MAX(id) FROM permissions), 1));
SELECT setval(pg_get_serial_sequence('role_permissions', 'id'), COALESCE((SELECT MAX(id) FROM role_permissions), 1));
SELECT setval(pg_get_serial_sequence('app_sections', 'id'), COALESCE((SELECT MAX(id) FROM app_sections), 1));
SELECT setval(pg_get_serial_sequence('section_actions', 'id'), COALESCE((SELECT MAX(id) FROM section_actions), 1));

